Lemma elemsW_forall' : forall (Q : Z * Z -> Prop) L, (forall e, In e L -> Q (e, e + 48)) -> Forall Q (elemsW L).
Proof. intros Q L K. unfold elemsW. apply Forall_forall. intros [l h] IN. apply in_map_iff in IN. destruct IN as (e & E1 & INe). injection E1 as <- <-. apply K. exact INe. Qed.

Lemma rin_elemsW' : forall L a, rin_ivs (elemsW L) a -> exists e, In e L /\ e <= a < e + 48.
Proof.
  induction L as [|e L IH]; intros a K; cbn in K; [destruct K|]. destruct K as [K|K]; [exists e; split; [left; reflexivity| exact K]|].
  destruct (IH a K) as (e' & IN & K'). exists e'. split; [right; exact IN| exact K'].
Qed.

Lemma in_elemsW' : forall L e a, In e L -> e <= a < e + 48 -> rin_ivs (elemsW L) a.
Proof. induction L as [|e0 L IH]; intros e a IN K; cbn; [destruct IN|]. destruct IN as [<-|IN]; [left; exact K| right; exact (IH e a IN K)]. Qed.

