  (* [comment removed for export] *)
  Lemma ipf_elem_facts : forall s LB m0 m Fa S L ns ls em,
    as_RHEAP H s LB m0 -> AFieldsC m Fa S L ns ls em -> AFieldsOwn LB em ->
    forall e, In e L -> exists d p, em !! e = Some d /\ In (p, e, esize d) LB /\ AIMG_TOP <= e /\ e + esize d <= aceil
          /\ (e + esize d <= ALOWSH_LO \/ AHI_LO <= e) /\ (e + esize d + 16 <= as_FSB H \/ as_FSB H + AFS_SIZE <= e - 16) /\ 60 <= esize d.
  Proof.
    intros s LB m0 m Fa S L ns ls em RH FC OWN e INe.
    pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LEQ & EOK & _).
    pose proof (proj1 (LEQ e) ltac:(apply (proj2 (list_elem_of_In _ _)); exact INe)) as SM.
    destruct (em !! e) as [d|] eqn:Ld; [| destruct SM as [? K]; discriminate K].
    destruct (OWN e d Ld) as (p & INb & _). pose proof (esize_ge d) as EG.
    pose proof (ah_blocks H HH _ _ _ _ RH INb) as (R1 & R2 & R3 & R4 & R5 & R6 & R7). cbn [blk_addr blk_size fst snd] in R1, R2, R3, R4, R5, R6, R7.
    pose proof (aapp_bounds _ _ R7 ltac:(clear - EG; lia)) as (B1 & B2 & B3 & B4 & B5). pose proof (aapp_not_shadowland _ _ R7) as NS.
    exists d, p. repeat split; try assumption; lia.
  Qed.

  (* [comment removed for export] *)
  Lemma elems_off_P : forall s LB m0 LF m1 m P S L ns ls em,
    as_RHEAP H s LB m0 -> as_RFS H LF m1 -> aobj LB LF P 256 -> AFieldsC m (P + 80) S L ns ls em -> AFieldsOwn LB em ->
    forall e d, em !! e = Some d -> P + 256 <= e \/ e + esize d <= P.
  Proof.
    intros s LB m0 LF m1 m P S L ns ls em RH RF AO FC OWN e d Ld.
    pose proof FC as (_ & _ & _ & _ & _ & _ & _ & _ & EOK & _ & _ & HS). pose proof (HS e d Ld) as SEP. pose proof (esize_ge d) as EG.
    destruct (OWN e d Ld) as (p & INb & _).
    pose proof (ah_blocks H HH _ _ _ _ RH INb) as (R1 & R2 & R3 & R4 & R5 & R6 & R7). cbn [blk_addr blk_size fst snd] in R1, R2, R3, R4, R5, R6, R7.
    destruct AO as [(b & Hb & B1 & B2)|(f & Hf & B1 & B2)].
    - destruct (Z.eq_dec (blk_id b) (blk_id (p, e, esize d))) as [EQ|NE].
      + (* [comment removed for export] *)
        pose proof (ah_blocks H HH _ _ _ _ RH Hb) as (Q1 & _).
        assert (SAME : b = (p, e, esize d)).
        { pose proof (ah_nodup H HH _ _ _ RH) as ND. clear - ND Hb INb EQ.
          induction LB as [|x l IH]; [destruct Hb|]. inversion ND as [|x' l' NI ND']; subst.
          destruct Hb as [<-|Hb]; destruct INb as [E2|INb]; [exact E2| | | exact (IH Hb INb ND')].
          - exfalso. apply NI. rewrite EQ. apply in_map_iff. eexists; split; [reflexivity| exact INb].
          - exfalso. apply NI. rewrite E2, <- EQ. apply in_map_iff. eexists; split; [reflexivity| exact Hb]. }
        subst b. cbn [blk_addr blk_size fst snd] in B1, B2. exfalso. clear - B1 B2 SEP EG. lia.
      + destruct (ah_disj H HH _ _ _ _ _ RH Hb INb NE) as [D|D]; cbn [blk_addr blk_size fst snd] in D; clear - D B1 B2 EG; lia.
    - pose proof (proj2 (ah_RFS_range H HH _ _ RF) f Hf) as (K & Q1 & Q2 & Q3 & Q4). pose proof (fsz_pos (ff_class f) ltac:(lia)).
      unfold AFS_HDR, AFS_SIZE in *. clear - B1 B2 Q1 Q2 R6 H0 EG. lia.
  Qed.
