  Lemma vx_facts : forall s LB m0 LF mW m P E p0 n ff fp S L ns ls em,
    as_RHEAP H s LB m0 -> as_RFS H LF mW -> aobj LB LF P 256 -> AFieldsC m (P + 80) S L ns ls em -> AFieldsOwn LB em ->
    (forall e d, em !! e = Some d -> E + 24 <= e \/ e + esize d <= E) ->
    (forall e, e ∈ L -> e + 48 <= p0 \/ p0 + n <= e) ->
    AIMG_TOP <= E -> E + 24 <= aceil -> (E + 24 <= ALOWSH_LO \/ AHI_LO <= E) -> AIMG_TOP <= P -> P + 256 <= aceil -> (P + 256 <= ALOWSH_LO \/ AHI_LO <= P) ->
    (P + 256 <= E \/ E + 24 <= P) -> (p0 + n <= E \/ E + 24 <= p0) -> (p0 + n <= P \/ P + 256 <= p0) ->
    (E + 24 <= ff \/ ff + 8192 <= E) -> (P + 256 <= ff \/ ff + 8192 <= P) -> (E + 24 <= fp \/ fp + 1 <= E) -> (P + 256 <= fp \/ fp + 1 <= P) ->
    as_FSB H + AFS_HDR <= ff -> ff + 8192 <= as_FSB H + AFS_SIZE -> as_FSB H + AFS_FLAGS <= fp -> fp < as_FSB H + AFS_HDR ->
    0x800c7e00 <= sh ff -> sh ff + 1024 <= AHI_LO ->
    let X' := (E, E + 24) :: (P + 80, P + 80 + 48) :: elemsW L in
       Forall noshadow X'
    /\ (forall A k, aceil <= A -> Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) X')
    /\ (forall A k, A + k <= AIMG_TOP -> Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) X')
    /\ Forall (fun iv : Z * Z => P + 80 <= fst iv \/ snd iv <= P) X'
    /\ Forall (fun iv : Z * Z => P + 242 + 1 <= fst iv \/ snd iv <= P + 242) X'
    /\ Forall (fun iv : Z * Z => p0 + n <= fst iv \/ snd iv <= p0) X'
    /\ (forall A k, ff <= A -> A + k <= ff + 8192 -> Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) X')
    /\ (forall A k, sh ff <= A -> A + k <= sh ff + 1024 -> Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) X')
    /\ Forall (fun iv : Z * Z => fp + 1 <= fst iv \/ snd iv <= fp) X'
    /\ Forall (fun iv : Z * Z => 0x125e40 <= fst iv \/ snd iv <= 0x115000) X'.
