(* [comment removed for export] *)
Definition ipf_static (sp tp : word) (LB0 : list block) (LF : list fframe) (P IN E lo B shi : Z) (c0 : pcore) (p0 : Z) (bs : list byte) : Prop :=
  ipf_pure sp P IN E lo shi c0 p0 bs
  /\ aobj LB0 LF P 256 /\ aobj LB0 LF E 24 /\ aobj LB0 LF p0 (Z.of_nat (length bs))
  /\ lb_bytes LB0 + 17 * Z.of_nat (length bs) <= as_LIVE_MAX H /\ Z.of_nat (length LB0) + Z.of_nat (length bs) / 4 <= as_LIVE_CNT_MAX H
  /\ bv_unsigned sp <= B /\ tp = Z_to_bv 64 ATP /\ (length LF + 2 < AFS_MAXLIVE)%nat /\ 0 <= P.

(* [comment removed for export] *)
Definition ipf_at_vcall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (sE : as_St H) (m0 : mem) (mo0 : Model) (LB0 : list block) (LF : list fframe) (P IN E lo B shi : Z) (c0 : pcore) (pad7 pad2 : list byte)
    (p0 : Z) (bs : list byte) (L0 : list Z) (mb : byte) (p : Z) (cf : config) : Prop :=
  exists (t0 t1 t2 t3 t4 t5 t6 : word) (m1 : mem) (c2 : pcore) (g1 : bool) (q p' f nlen vptr vlen bsz : Z) (nbs vbs : list byte)
         (spa : Z) (gsz : nat) (gj : list byte) (ff fp : Z) (h3 : word) (j0 j128 jr jh jt bb : list byte)
         (sA : as_St H) (LBn : list block) (S1 L1 : list Z) (ns1 : NS) (ls1 : LS) (em1 : gmap Z elt) (errv1 : word) (XS : list (Z * Z)),
    as_VIS H sA (cfg_ms cf)
      = MS (mkR (wz AIPF_VRET) (wz spa) gp tp t0 t1 t2 sp (wz spa)
                (wz P) (wz f) (wz p) (wz nlen) (wz vptr) (wz vlen) (wz E) (wz (ipf_slot_target (pc_state c0)))
                (wz IN) (wz E) (wz (sh7 ff)) (wz f) (wz (sh7 (E + 16))) (wz (sh7 E)) (wz P) (wz (E + 16)) (wz ASHADOW_BASE) (wz IN) t3 t4 t5 t6)
           F (wz (ipf_slot_target (pc_state c0))) fc None m1 (seg_rom asegs)
    /\ as_AKREL H sA cf /\ as_MPRES H mo0 (cfg_model cf)
    /\ rw_cells asegs m1 (errno_addr tp) [C4 errv1] /\ as_rauxv_ok H m1 B
    /\ as_RHEAP H sA (LBn ++ LB0) m1
    /\ AFieldsC m1 (P + 80) S1 L1 ns1 ls1 em1 /\ AFieldsOwn (LBn ++ LB0) em1 /\ new_elems_off H LB0 (bv_unsigned sp) L0 L1
    /\ lsub L0 L1 /\ lbn_own L1 LBn
    /\ (forall e, e ∈ L1 -> e + 48 <= p0 \/ p0 + Z.of_nat (length bs) <= e)
    /\ (forall e d, em1 !! e = Some d -> E + 24 <= e \/ e + esize d <= E)
    /\ Forall (fs_scratch H LF) XS /\ xpres H LB0 (bv_unsigned sp) (ipf_X P IN E L0 ++ XS) m0 m1
    /\ lb_bytes LBn <= 17 * (p - p0) /\ 4 * Z.of_nat (length LBn) <= p - p0
    /\ as_AL H sA >= as_AL H sE - as_Cm H (17 * (p - p0))
    /\ ipf_ctx H LF m1 m1 sp spa gsz gj ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 P IN E p0 bs c2 pad7 pad2 q (ErrCodeCells EC_clear) g1
               lo shi ff fp (p0 + Z.of_nat (length bs)) (wz 0x41b58ab3) (wz 0x13fb2) (wz 0xd0474) h3 IPF_SH0 j0 j128 jr jh []
    /\ ipf_frame m1 spa ff jt p' bsz bb [C8 (wz vptr); C8 (wz vlen)] [C8 (wz p); C8 (wz nlen)]
    /\ ipf_bpure sp spa gsz P IN E lo shi c0 p0 (p0 + Z.of_nat (length bs)) bs
    /\ dof_core c0 c2 /\ (pc_state c0 = 10 -> c2 = c0)
    /\ rw_cells asegs m1 (P + O_PR_MERGE) [C1 mb] /\ FT m1
    /\ bytes_at asegs m1 p nbs /\ Z.of_nat (length nbs) = nlen /\ f = ft_lookup (zbytes nbs)
    /\ bytes_at asegs m1 vptr vbs /\ Z.of_nat (length vbs) = vlen
    /\ pf_succ p (p0 + Z.of_nat (length bs)) (ff + 40) p' nlen vptr vlen bsz /\ p0 <= p /\ p0 <= q <= p.

(* [comment removed for export] *)
Definition ipf_after_cb (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (sE : as_St H) (m0 : mem) (mo0 : Model) (LB0 : list block) (LF : list fframe) (P IN E lo B shi : Z) (c0 : pcore) (pad7 pad2 : list byte)
    (p0 : Z) (bs : list byte) (L0 : list Z) (mb : byte) (p' : Z) (cf : config) : Prop :=
  exists (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5x t3 t4 t5 t6 : word) (m3 : mem) (c2 : pcore) (g3 : bool) (q bsz : Z)
         (spa : Z) (gsz : nat) (gj : list byte) (ff fp : Z) (h3 : word) (j0 j128 jr jh jt bb : list byte) (vl nm : list cell)
