                (wz IN) (wz E) (wz (sh7 ff)) s5x (wz (sh7 (E + 16))) (wz (sh7 E)) (wz P) (wz (E + 16)) (wz ASHADOW_BASE) (wz IN) t3 t4 t5 t6)
