(* [comment removed for export] *)
Lemma ipf_seg_carry : forall (s : as_St H) (LB1 LB0 : list block) (LF : list fframe) (m0 mW m3 m4 : mem) (XS4 XS : list (Z * Z)) (sp tp : word)
    (lo shi B P IN E p0 : Z) (bs : list byte) (c : pcore) (L0 L1 S1 : list Z) (ns1 : NS) (ls1 : LS) (em1 : gmap Z elt) (errv : word) (mb : byte),
  as_RHEAP H s LB1 m3 -> as_RFS H LF mW -> (forall b, In b LB0 -> In b LB1) ->
  aobj LB0 LF P 256 -> aobj LB0 LF E 24 -> aobj LB0 LF p0 (Z.of_nat (length bs)) -> ipf_pure sp P IN E lo shi c p0 bs ->
  AFieldsC m3 (P + 80) S1 L1 ns1 ls1 em1 -> AFieldsOwn LB1 em1 -> (forall e d, em1 !! e = Some d -> E + 24 <= e \/ e + esize d <= E) ->
  Forall (fs_scratch H LF) XS4 -> munch (ipf_W lo sp P IN E ++ XS4) m3 m4 -> wmono asegs m3 m4 ->
  tp = Z_to_bv 64 ATP -> rw_cells asegs m3 (errno_addr tp) [C4 errv] -> as_rauxv_ok H m3 B -> rw_cells asegs m3 (P + O_PR_MERGE) [C1 mb] ->
  Forall (fs_scratch H LF) XS -> xpres H LB0 (bv_unsigned sp) (ipf_X P IN E L0 ++ XS) m0 m3 ->
     rw_cells asegs m4 (errno_addr tp) [C4 errv] /\ as_rauxv_ok H m4 B /\ as_RHEAP H s LB1 m4 /\ AFieldsC m4 (P + 80) S1 L1 ns1 ls1 em1
  /\ rw_cells asegs m4 (P + O_PR_MERGE) [C1 mb]
  /\ Forall (fs_scratch H LF) (XS ++ XS4) /\ xpres H LB0 (bv_unsigned sp) (ipf_X P IN E L0 ++ (XS ++ XS4)) m0 m4.
Proof.
  intros until mb. intros RH RF LBS AOP AOE AOW PURE FC OWN EOE FXS4 MU WM TPV ERR AUX MB FXS XP.
  pose proof PURE as (PCOK & LBSZ & LO & CEIL & PAL & EAL & SPI & ISH & IAL & DPE & DWP & DWE & SPAL & SHI). unfold IPF_STACK in LO.
  pose proof aceil_facts as (AF1 & _).
  pose proof (aobj_LB_mono _ _ _ _ _ AOP LBS) as AOP1. pose proof (aobj_LB_mono _ _ _ _ _ AOE LBS) as AOE1. pose proof (aobj_LB_mono _ _ _ _ _ AOW LBS) as AOW1.
  pose proof (aobj_aapp H HH _ _ _ _ _ _ _ RH RF AOP1) as APP. pose proof (aobj_aapp H HH _ _ _ _ _ _ _ RH RF AOE1) as APE.
  pose proof (aapp_bounds _ _ APP ltac:(clear; lia)) as (PB1 & PB2 & PB3 & PB4 & _). pose proof (aapp_bounds _ _ APE ltac:(clear; lia)) as (EB1 & EB2 & EB3 & EB4 & _).
  unfold AIMG_TOP, AAPP_HI in PB1, PB3, EB1, EB3.
  assert (EA : errno_addr tp = AERRNO) by (rewrite TPV; unfold AERRNO, ATP; rewrite unsigned_lit; [reflexivity| clear; lia]). rewrite EA in ERR |- *.
  pose proof (scratch_Forall H HH LF mW LB1 XS4 RF FXS4) as (SCW & SCLO & SCHI).
  pose proof (ipf_elem_facts H HH _ _ _ _ _ _ _ _ _ _ RH FC OWN) as EL. pose proof (elems_off_P H HH _ _ _ _ _ _ _ _ _ _ _ _ RH RF AOP1 FC OWN) as EOP.
  (* [comment removed for export] *)
  destruct (stack_window_ok' H HH s LB1 m3 LF lo (bv_unsigned sp) RH CEIL) as (WS1 & WS2 & WS3).
  destruct (aobj_write_ok H HH _ _ _ _ _ _ _ RH RF (aobj_sub _ _ _ _ P 80 AOP1 ltac:(clear; lia) ltac:(clear; lia))) as (WP1 & WP2 & WP3).
  destruct (stack_window_ok' H HH s LB1 m3 LF IN (IN + 8) RH ltac:(clear - CEIL LO SPI; lia)) as (WI1 & WI2 & WI3).
  destruct (aobj_write_ok H HH _ _ _ _ _ _ _ RH RF AOE1) as (WE1 & WE2 & WE3).
  destruct (ipf_cat_window_ok H HH _ _ _ _ _ RH RF) as (WC1 & WC2 & WC3).
  destruct (ipf_tab_window_ok H HH _ _ _ _ _ RH RF) as (WT1 & WT2).
  assert (FWC : Forall (aclient_write_ok H LB1) (ipf_W lo sp P IN E ++ XS4)).
  { apply Forall_app. split; [| exact SCW]. unfold ipf_W. repeat apply Forall_cons; [exact WS1| exact WP1| exact WI1| exact WE1| exact WC1| exact WT1| apply Forall_nil]. }
  assert (FAW : Forall awin (ipf_W lo sp P IN E)).
  { unfold ipf_W. repeat apply Forall_cons; [apply awin_stack; exact CEIL| eapply awin_aapp; [exact APP| clear; lia| clear; lia]
      | apply awin_stack; clear - CEIL LO SPI; lia| eapply awin_aapp; [exact APE| clear; lia| clear; lia]| exact (proj1 pwin_httpcat)| apply ft_tab_awin; clear; lia| apply Forall_nil]. }
  split; [| split; [| split; [| split; [| split; [| split]]]]].
  - eapply (rw_cells_transport asegs _ m3 m4); [exact ERR| exact MU| exact WM|]. apply disjoint_from_app2.
    + unfold ipf_W. cbn [disjoint_from fst snd cells_size csize Nat.add]. unfold AERRNO, ATP, AG_HTTP_CAT, AG_FIELD_TABLE. clear - PB1 EB1 CEIL AF1 LO SPI. lia.
    + apply SCLO. unfold AERRNO, ATP, AIMG_TOP. cbn. clear. lia.
  - exact (ah_rauxv_frame H HH LB1 _ _ _ _ AUX MU WM FWC).
  - exact (ah_RHEAP_frame H HH s LB1 m3 m4 _ RH MU WM FWC).
  - eapply (AFieldsC_transport_scr H HH s LB1 m3 LF mW); [exact RH| exact RF| exact FC| exact OWN| eapply aobj_sub; [exact AOP1| clear; lia| clear; lia]
      | exact MU| exact WM| exact FAW| exact FXS4| |].
    + unfold ipf_W. cbn [disjoint_from fst snd]. unfold AG_HTTP_CAT, AG_FIELD_TABLE. clear - PB1 PB2 CEIL LO SPI DPE. lia.
    + pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LEQ & _).
      intros e d Ld. assert (INe : In e L1) by (apply (proj1 (list_elem_of_In _ _)); apply (proj2 (LEQ e)); rewrite Ld; eexists; reflexivity).
      destruct (EL e INe) as (d' & p & Ld' & _ & K1 & K2 & _ & _ & K5).
      rewrite Ld in Ld'. injection Ld' as <-.
      pose proof (EOP e d Ld) as KP. pose proof (EOE e d Ld) as KE.
      unfold ipf_W. cbn [disjoint_from fst snd]. unfold AG_HTTP_CAT, AG_FIELD_TABLE, AIMG_TOP in *. clear - K1 K2 K5 KP KE CEIL LO SPI. lia.
  - eapply (rw_cells_transport asegs _ m3 m4); [exact MB| exact MU| exact WM|]. apply disjoint_from_app2.
    + unfold ipf_W. cbn [disjoint_from fst snd cells_size csize Nat.add]. unfold O_PR_MERGE, AG_HTTP_CAT, AG_FIELD_TABLE. clear - PB1 PB2 CEIL AF1 LO SPI DPE. lia.
    + eapply (disjoint_scratch H HH); [exact RF| eapply fsobj_sub; [exact (aobj_fsobj H HH _ _ _ _ _ _ RH AOP1)| unfold O_PR_MERGE; clear; lia| unfold O_PR_MERGE; cbn; clear; lia]
        | cbn; clear; lia| unfold O_PR_MERGE, AAPP_HI; cbn; clear - PB3; lia| eapply aapp_sub; [exact APP| unfold O_PR_MERGE; clear; lia| unfold O_PR_MERGE; cbn; clear; lia]| exact FXS4].
  - apply Forall_app. split; [exact FXS| exact FXS4].
  - eapply xpres_trans.
    + eapply xpres_weaken; [exact XP| clear; lia| intros b Hb; exact Hb|]. intros a K. rewrite app_assoc. apply rin_ivs_app. left. exact K.
    + eapply xpres_weaken with (LB := LB1) (SP := bv_unsigned sp); [| clear; lia| exact LBS| intros a K; exact K].
      eapply xpres_of_munch with (s := s) (m0 := m3); [exact HH| exact RH| exact MU| exact WM|].
      apply Forall_app. split.
      * unfold ipf_W, ipf_X. repeat apply Forall_cons; [| | | | | | apply Forall_nil]; cbn [fst snd].
        -- left. clear - CEIL. lia.
        -- right. intros a Ha. apply rin_ivs_app. left. cbn [rin_ivs fst snd]. left. clear - Ha. lia.
        -- right. intros a Ha. apply rin_ivs_app. left. cbn [rin_ivs fst snd]. right; left. exact Ha.
        -- right. intros a Ha. apply rin_ivs_app. left. cbn [rin_ivs fst snd]. right; right; left. exact Ha.
        -- right. intros a Ha. apply rin_ivs_app. left. cbn [rin_ivs fst snd]. right; right; right; left. exact Ha.
        -- right. intros a Ha. apply rin_ivs_app. left. cbn [rin_ivs fst snd]. right; right; right; right; left. exact Ha.
      * apply Forall_forall. intros [l h] INx. right. cbn [fst snd]. intros a Ha. apply rin_ivs_app. right. apply rin_ivs_app. right.
        clear - INx Ha. induction XS4 as [|iv XS4 IH]; [destruct INx|]. destruct INx as [E|INx]; cbn; [rewrite E; cbn; left; exact Ha| right; exact (IH INx)].
Qed.

