Lemma aclient_addr_range1 : forall LB SP a, aclient_addr H LB SP a -> aclient_range H LB SP a 1.
Proof.
  intros LB SP a K. unfold aclient_addr, aclient_range in *.
  destruct K as [K|[K|[[b [Hb K]]|[[b [Hb K]]|[K|[K|K]]]]]].
  - left; exact K.
